// Matrices, angles, and moving points between the spaces of entities.

#include "scene_internal.hpp"

using namespace bb;
using namespace bb::scene;

namespace bb::scene {

	// Rotation matrix: roll (Z) first, then pitch (X), then yaw (Y). 3x3, column-major.
	void rotation_matrix(float* r, const float* rotation)
	{
		float cp = cosf(rad(rotation[0])), sp = sinf(rad(rotation[0]));
		float cy = cosf(rad(rotation[1])), sy = sinf(rad(rotation[1]));
		float cr = cosf(rad(rotation[2])), sr = sinf(rad(rotation[2]));
		// The columns of Ry * Rx * Rz are the images of +X, +Y and +Z. Start with those of Rz:
		// +X -> (cr, sr, 0), +Y -> (-sr, cr, 0), +Z -> (0, 0, 1). A positive roll turns the top to the left, like a positive yaw.
		float x0[3] = { cr, sr, 0 }, y0[3] = { -sr, cr, 0 }, z0[3] = { 0, 0, 1 };
		float* in[3] = { x0, y0, z0 };
		for (int c = 0; c < 3; c++) {
			float* v = in[c];
			// Rx: y' = y cp - z sp, z' = y sp + z cp
			float x1 = v[0], y1 = v[1] * cp - v[2] * sp, z1 = v[1] * sp + v[2] * cp;
			// Ry, turned the way Blitz does it (a positive yaw turns left): x' = x cy - z sy, z' = x sy + z cy
			float x2 = x1 * cy - z1 * sy, y2 = y1, z2 = x1 * sy + z1 * cy;
			r[c * 3 + 0] = x2;
			r[c * 3 + 1] = y2;
			r[c * 3 + 2] = z2;
		}
	}

	void local_matrix(entity const& e, float* m)
	{
		float r[9];
		rotation_matrix(r, e.rotation);
		for (int c = 0; c < 3; c++) {
			for (int row = 0; row < 3; row++) {
				m[c * 4 + row] = r[c * 3 + row] * e.scale[c];
			}
			m[c * 4 + 3] = 0;
		}
		m[12] = e.position[0];
		m[13] = e.position[1];
		m[14] = e.position[2];
		m[15] = 1;
	}

	void transform_point(const float* m, const float* p, float* out)
	{
		for (int row = 0; row < 3; row++) {
			out[row] = m[0 + row] * p[0] + m[4 + row] * p[1] + m[8 + row] * p[2] + m[12 + row];
		}
	}

	// Inverse of an affine matrix (rotation, scale and translation).
	void affine_inverse(const float* m, float* out)
	{
		float a = m[0], b = m[4], c = m[8], d = m[1], e = m[5], f = m[9], g = m[2], h = m[6], i = m[10];
		float det = a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
		float inv = (fabsf(det) > 1e-12f) ? 1.0f / det : 0.0f;
		float r[9] = {
			(e * i - f * h) * inv, (c * h - b * i) * inv, (b * f - c * e) * inv,
			(f * g - d * i) * inv, (a * i - c * g) * inv, (c * d - a * f) * inv,
			(d * h - e * g) * inv, (b * g - a * h) * inv, (a * e - b * d) * inv,
		};
		mat_identity(out);
		for (int row = 0; row < 3; row++) {
			for (int col = 0; col < 3; col++) {
				out[col * 4 + row] = r[row * 3 + col];
			}
		}
		out[12] = -(out[0] * m[12] + out[4] * m[13] + out[8] * m[14]);
		out[13] = -(out[1] * m[12] + out[5] * m[13] + out[9] * m[14]);
		out[14] = -(out[2] * m[12] + out[6] * m[13] + out[10] * m[14]);
	}

	void parent_matrix(entity const& e, float* m)
	{
		if (e.parent) {
			world_matrix(e.parent, m);
		} else {
			mat_identity(m);
		}
	}

	// Blitz offers "global" variants of many functions, which work in world space instead of the parent's.
	void world_to_local_point(entity const& e, const float* world, float* local)
	{
		float pm[16], inv[16];
		parent_matrix(e, pm);
		affine_inverse(pm, inv);
		transform_point(inv, world, local);
	}

	void length_normalize(float* v)
	{
		float len = sqrtf(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
		if (len > 1e-12f) {
			v[0] /= len;
			v[1] /= len;
			v[2] /= len;
		}
	}

	// Pitch, yaw and roll that produce the given rotation matrix (columns are the entity's axes).
	void euler_from_matrix_impl(const float* m, float* out)
	{
		float x[3] = { m[0], m[1], m[2] }, y[3] = { m[4], m[5], m[6] }, z[3] = { m[8], m[9], m[10] };
		length_normalize(x);
		length_normalize(y);
		length_normalize(z);
		float s = -z[1];
		s       = s > 1 ? 1 : (s < -1 ? -1 : s);
		out[0]  = deg(asinf(s));
		out[1]  = deg(atan2f(-z[0], z[2]));
		out[2]  = deg(atan2f(x[1], y[1]));
	}

	////////////////////////////////////////////////////////////////////////////////
	// Angles and conversions between spaces
	////////////////////////////////////////////////////////////////////////////////
	static float wrap_angle(float angle)
	{
		while (angle > 180.0f) {
			angle -= 360.0f;
		}
		while (angle <= -180.0f) {
			angle += 360.0f;
		}
		return angle;
	}

	// Moves a point (or direction) from the space of one entity to that of another. 0 is the world.
	static void transform_between(float x, float y, float z, int32_t source, int32_t destination, bool point, bool normalize)
	{
		float p[3] = { x, y, z }, out[3];
		float m[16], inverse[16];
		if (source) {
			world_matrix(source, m);
			if (point) {
				transform_point(m, p, out);
			} else {
				for (int row = 0; row < 3; row++) {
					out[row] = m[0 + row] * p[0] + m[4 + row] * p[1] + m[8 + row] * p[2];
				}
			}
			memcpy(p, out, sizeof(p));
		}
		if (destination) {
			world_matrix(destination, m);
			affine_inverse(m, inverse);
			if (point) {
				transform_point(inverse, p, out);
			} else {
				for (int row = 0; row < 3; row++) {
					out[row] = inverse[0 + row] * p[0] + inverse[4 + row] * p[1] + inverse[8 + row] * p[2];
				}
			}
			memcpy(p, out, sizeof(p));
		}
		if (normalize) {
			length_normalize(p);
		}
		memcpy(tformed, p, sizeof(p));
	}
} // namespace bb::scene


void bb::euler_from_matrix(const float* m, float* euler)
{
	::euler_from_matrix_impl(m, euler);
}

void bb::mat_identity(float* m)
{
	memset(m, 0, sizeof(float) * 16);
	m[0] = m[5] = m[10] = m[15] = 1;
}

void bb::mat_multiply(float* out, const float* a, const float* b)
{
	float r[16];
	for (int c = 0; c < 4; c++) {
		for (int row = 0; row < 4; row++) {
			float sum = 0;
			for (int k = 0; k < 4; k++) {
				sum += a[k * 4 + row] * b[c * 4 + k];
			}
			r[c * 4 + row] = sum;
		}
	}
	memcpy(out, r, sizeof(r));
}

void bb::mat_affine_inverse(const float* m, float* out)
{
	affine_inverse(m, out);
}

extern "C" {

// How far entity would have to turn to look at the target.
float bb_delta_yaw(int32_t handle, int32_t target)
{
	need(handle, "DeltaYaw");
	need(target, "DeltaYaw");
	float me[16], to[16], angles[3];
	world_matrix(handle, me);
	world_matrix(target, to);
	euler_from_matrix_impl(me, angles);
	return wrap_angle(deg(atan2f(me[12] - to[12], to[14] - me[14])) - angles[1]);
}

float bb_delta_pitch(int32_t handle, int32_t target)
{
	need(handle, "DeltaPitch");
	need(target, "DeltaPitch");
	float me[16], to[16], angles[3];
	world_matrix(handle, me);
	world_matrix(target, to);
	euler_from_matrix_impl(me, angles);
	float d[3] = { to[12] - me[12], to[13] - me[13], to[14] - me[14] };
	float len  = sqrtf(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
	if (len < 1e-9f) {
		return 0;
	}
	return wrap_angle(deg(asinf(-d[1] / len)) - angles[0]);
}

void bb_tform_point(float x, float y, float z, int32_t source, int32_t destination)
{
	if (source) {
		need(source, "TFormPoint");
	}
	if (destination) {
		need(destination, "TFormPoint");
	}
	transform_between(x, y, z, source, destination, true, false);
}

void bb_tform_vector(float x, float y, float z, int32_t source, int32_t destination)
{
	if (source) {
		need(source, "TFormVector");
	}
	if (destination) {
		need(destination, "TFormVector");
	}
	transform_between(x, y, z, source, destination, false, false);
}

void bb_tform_normal(float x, float y, float z, int32_t source, int32_t destination)
{
	if (source) {
		need(source, "TFormNormal");
	}
	if (destination) {
		need(destination, "TFormNormal");
	}
	transform_between(x, y, z, source, destination, false, true);
}

float bb_tformed_x(void) { return tformed[0]; }
float bb_tformed_y(void) { return tformed[1]; }
float bb_tformed_z(void) { return tformed[2]; }
}
